import rules_lib

def check(ctx):
    cltv = ctx['LoanCore.cltv_percent']
    missing = rules_lib.gaps(cltv=cltv)
    if missing:
        return rules_lib.unknown(*missing)

    if cltv <= 80.00:
        return True

    property_type = ctx['SubjectProperty.property_type']
    missing = rules_lib.gaps(property_type=property_type)
    if missing:
        return rules_lib.unknown(*missing)

    if rules_lib.same(property_type, 'SFR', 'Townhome', 'PUD'):
        return True

    if rules_lib.same(property_type, 'Warrantable Condo'):
        state = ctx['SubjectProperty.state']
        missing = rules_lib.gaps(state=state)
        if missing:
            return rules_lib.unknown(*missing)
        return not rules_lib.same(state, 'Florida')

    return False

import rules_lib


def check(ctx):
    property_type = ctx['SubjectProperty.property_type']
    if not rules_lib.known(property_type):
        return rules_lib.unknown('SubjectProperty.property_type')
    if rules_lib.match(property_type, ['Condotel / PUDtel']) is None:
        return True

    purpose = ctx['LoanCore.loan_purpose']
    state = ctx['SubjectProperty.state']
    cltv = ctx['LoanCore.cltv_percent']
    missing = rules_lib.gaps(loan_purpose=purpose, state=state, cltv_percent=cltv)
    if missing:
        return rules_lib.unknown(*missing)

    purpose_match = rules_lib.match(purpose, ['Purchase', 'Refi R/T', 'Refi C/O'])
    if purpose_match is None:
        return rules_lib.unknown('LoanCore.loan_purpose')

    if rules_lib.same(purpose_match, 'Purchase'):
        limit = 75
    elif rules_lib.same(purpose_match, 'Refi R/T'):
        limit = 70
    else:
        limit = 65

    if rules_lib.same(state, 'Florida', 'FL'):
        limit -= 5

    meets_limit = rules_lib.band(cltv, [(limit, True)], above=False)
    if meets_limit is None:
        return rules_lib.unknown('LoanCore.cltv_percent')
    return meets_limit

