def check(ctx):
    listed_raw = ctx['SubjectProperty.listed_for_sale_last_6_months']
    missing = rules_lib.gaps(listed=listed_raw)
    if missing:
        return rules_lib.unknown(*missing)
    listed = rules_lib.flag(listed_raw)
    if listed is None:
        return rules_lib.unknown('listed_for_sale_last_6_months')
    if not listed:
        return True

    occupancy_subtype = ctx['SubjectProperty.occupancy_subtype']
    reserves_months = ctx['RatioSet.reserves_months']
    interest_only_raw = ctx['MortgageLoanInformation.is_interest_only']
    missing = rules_lib.gaps(
        occupancy_subtype=occupancy_subtype,
        reserves_months=reserves_months,
        interest_only=interest_only_raw,
    )
    if missing:
        return rules_lib.unknown(*missing)

    interest_only = rules_lib.flag(interest_only_raw)
    if interest_only is None:
        return rules_lib.unknown('interest_only')

    investment_property = rules_lib.same(
        occupancy_subtype, 'investment', 'investment property'
    )
    if investment_property:
        lease_raw = ctx['SubjectProperty.has_current_lease']
        vacant_raw = ctx['SubjectProperty.is_vacant']
        missing = rules_lib.gaps(has_current_lease=lease_raw, is_vacant=vacant_raw)
        if missing:
            return rules_lib.unknown(*missing)
        has_current_lease = rules_lib.flag(lease_raw)
        is_vacant = rules_lib.flag(vacant_raw)
        if has_current_lease is None:
            return rules_lib.unknown('has_current_lease')
        if is_vacant is None:
            return rules_lib.unknown('is_vacant')
        if not has_current_lease or is_vacant:
            return False

    try:
        reserves_sufficient = reserves_months >= 24
    except (TypeError, ValueError):
        return rules_lib.unknown('reserves_months')

    return reserves_sufficient and not interest_only

