def check(ctx):
    vacant_raw = ctx['SubjectProperty.is_vacant']
    purpose = ctx['LoanCore.loan_purpose']
    missing = rules_lib.gaps(vacant=vacant_raw, purpose=purpose)
    if missing:
        return rules_lib.unknown(*missing)

    vacant = rules_lib.flag(vacant_raw)
    if vacant is None:
        return rules_lib.unknown('SubjectProperty.is_vacant')
    if not vacant or not rules_lib.same(purpose, 'rate and term refinance'):
        return True

    amount = ctx['LoanCore.total_loan_amount_usd']
    interest_only_raw = ctx['MortgageLoanInformation.is_interest_only']
    escrow_waived_raw = ctx['LoanCore.is_escrow_waived']
    reserves = ctx['RatioSet.reserves_months']
    missing = rules_lib.gaps(
        amount=amount,
        interest_only=interest_only_raw,
        escrow_waived=escrow_waived_raw,
        reserves=reserves,
    )
    if missing:
        return rules_lib.unknown(*missing)

    interest_only = rules_lib.flag(interest_only_raw)
    escrow_waived = rules_lib.flag(escrow_waived_raw)
    if interest_only is None:
        return rules_lib.unknown('MortgageLoanInformation.is_interest_only')
    if escrow_waived is None:
        return rules_lib.unknown('LoanCore.is_escrow_waived')

    if interest_only or escrow_waived or reserves < 6:
        return False

    # Exact amount boundaries are left to Acra confirmation. Between the
    # boundaries, the stated lower-amount and higher-amount bands apply.
    if amount < 1000000:
        cltv = ctx['LoanCore.cltv_percent']
        missing = rules_lib.gaps(cltv=cltv)
        if missing:
            return rules_lib.unknown(*missing)
        if cltv > 70:
            return False
    elif 1000000 < amount < 2000000:
        cltv = ctx['LoanCore.cltv_percent']
        missing = rules_lib.gaps(cltv=cltv)
        if missing:
            return rules_lib.unknown(*missing)
        if cltv > 65:
            return False

    return True

