import rules_lib

def check(ctx):
    loan_amount = ctx['LoanCore.total_loan_amount_usd']
    missing = rules_lib.gaps(loan_amount=loan_amount)
    if missing:
        return rules_lib.unknown(*missing)
    try:
        amount = decimal.Decimal(str(loan_amount))
    except (decimal.InvalidOperation, ValueError):
        return rules_lib.unknown('loan_amount')
    if not amount.is_finite():
        return rules_lib.unknown('loan_amount')
    return amount >= decimal.Decimal('100000') and amount <= decimal.Decimal('3000000') and amount % decimal.Decimal('50') == 0

