def check(ctx):
    has_event = ctx['Borrower.has_bankruptcy_or_foreclosure']
    seasoning = ctx['Borrower.months_since_bankruptcy_or_foreclosure']
    cltv = ctx['LoanCore.cltv_percent']
    purpose = ctx['LoanCore.loan_purpose']

    missing = rules_lib.gaps(
        has_bankruptcy_or_foreclosure=has_event,
        months_since_bankruptcy_or_foreclosure=seasoning,
        cltv_percent=cltv,
        loan_purpose=purpose,
    )
    if missing:
        return rules_lib.unknown(*missing)

    has_event = rules_lib.flag(has_event)
    if has_event is None:
        return rules_lib.unknown('has_bankruptcy_or_foreclosure')
    if not has_event:
        return True

    is_purchase = rules_lib.same(purpose, 'Purchase')
    is_refi = rules_lib.same(purpose, 'Refi R/T', 'Refi C/O')
    if not is_purchase and not is_refi:
        return rules_lib.unknown('loan_purpose')

    if seasoning < 12:
        return False
    if seasoning >= 36:
        return True

    if 24 <= seasoning <= 35:
        maximum = 80 if is_purchase else 75
    elif 12 <= seasoning <= 23:
        maximum = 65
    else:
        return rules_lib.unknown('months_since_bankruptcy_or_foreclosure')

    within_limit = rules_lib.band(cltv, [(maximum, True)], above=False)
    if within_limit is None:
        return rules_lib.unknown('cltv_percent')
    return within_limit

