def check(ctx):
    history = ctx['CreditReport.housing_history_rating']
    purpose = ctx['LoanCore.loan_purpose']
    cltv = ctx['LoanCore.cltv_percent']

    missing = rules_lib.gaps(history=history, purpose=purpose, cltv=cltv)
    if missing:
        return rules_lib.unknown(*missing)

    if rules_lib.same(history, '0x120x12'):
        return False

    if rules_lib.same(purpose, 'Purchase'):
        if rules_lib.same(history, '1x30x12'):
            limit = 80
        elif rules_lib.same(history, '0x60x12'):
            limit = 75
        elif rules_lib.same(history, '0x90x12'):
            limit = 65
        else:
            return rules_lib.unknown('housing_history_rating')
    elif rules_lib.same(purpose, 'Refi R/T', 'Refi C/O'):
        if rules_lib.same(history, '1x30x12'):
            limit = 75
        elif rules_lib.same(history, '0x60x12'):
            limit = 70
        elif rules_lib.same(history, '0x90x12'):
            limit = 65
        else:
            return rules_lib.unknown('housing_history_rating')
    else:
        return rules_lib.unknown('loan_purpose')

    if not rules_lib.known(cltv):
        return rules_lib.unknown('cltv')
    try:
        return float(cltv) <= limit
    except (TypeError, ValueError):
        return rules_lib.unknown('cltv')

