def check(ctx):
    seasoning = ctx['Borrower.months_since_short_sale_dil_or_modification']
    cltv = ctx['LoanCore.cltv_percent']
    purpose = ctx['LoanCore.loan_purpose']

    missing = rules_lib.gaps(
        seasoning=seasoning,
        cltv=cltv,
        loan_purpose=purpose,
    )
    if missing:
        return rules_lib.unknown(*missing)

    numeric_seasoning = rules_lib.band(seasoning, [(0, True)], above=True)
    if numeric_seasoning is None:
        return rules_lib.unknown('Borrower.months_since_short_sale_dil_or_modification')

    if seasoning >= 24:
        return True
    if seasoning < 12:
        tier = 'under_12'
    else:
        tier = '12_23'

    if rules_lib.same(purpose, 'purchase'):
        limit = 75 if tier == 'under_12' else 80
    elif rules_lib.same(purpose, 'refi r/t', 'refi c/o'):
        limit = 70 if tier == 'under_12' else 75
    else:
        return rules_lib.unknown('LoanCore.loan_purpose')

    within_limit = rules_lib.band(cltv, [(limit, True)], above=False)
    if within_limit is None:
        return rules_lib.unknown('LoanCore.cltv_percent')
    return within_limit

