import rules_lib

def check(ctx):
    citizenship = ctx['Borrower.citizenship_status']
    purpose = ctx['LoanCore.loan_purpose']
    cltv = ctx['LoanCore.cltv_percent']

    missing = rules_lib.gaps(citizenship=citizenship, purpose=purpose, cltv=cltv)
    if missing:
        return rules_lib.unknown(*missing)

    if not rules_lib.same(citizenship, 'Foreign National'):
        return True

    if rules_lib.same(purpose, 'purchase'):
        return cltv <= 70

    is_rate_term = any(rules_lib.same(purpose, option) for option in (
        'rate & term',
        'rate & term refinance',
        'refinance rate & term',
    ))
    is_cash_out = any(rules_lib.same(purpose, option) for option in (
        'cash-out',
        'cash-out refinance',
        'refinance cash-out',
    ))
    if is_rate_term or is_cash_out:
        return cltv <= 65

    return True

