        return rules_lib.unknown(*missing)

    meets_us_report_option = rules_lib.flag(tradelines)
    if meets_us_report_option is None:
        return rules_lib.unknown('CreditReport.tradelines_meet_requirement')
    if meets_us_report_option:
        return True

    # The U.S. credit-report option is not met; the other permitted options
    # are not represented by any allowed case field.
    return rules_lib.unknown('other_permitted_credit_reference')

